import { test, expect } from '@playwright/test';

test.describe('Multiple File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully upload multiple files at once', async ({ page }) => {
    // Setup: intercept the upload API
    await page.route('**/api/files/upload', (route) => {
      route.continue();
    });

    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload files');
    await fileInput.setInputFiles('playwright/fixtures/file1.pdf', 'playwright/fixtures/file2.jpg', 'playwright/fixtures/file3.docx');

    // Verify file names are displayed
    const fileList = page.getByRole('list');
    await expect(fileList).toBeVisible();

    const fileItems = page.getByRole('listitem');
    const count = await fileItems.count();
    expect(count).toBe(3);

    // Verify each file name is visible
    const fileNames = page.getByText(/file1\.pdf|file2\.jpg|file3\.docx/);
    await expect(fileNames).toBeVisible();

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for upload confirmation
    await page.waitForResponse(response => 
      response.url().includes('/api/files/upload') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText(/files uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify success icon is displayed
    const successIcon = page.getByRole('img', { name: /success/i });
    await expect(successIcon).toBeVisible();
  });

  test('should handle file upload with validation errors', async ({ page }) => {
    // Setup: intercept the upload API and return an error
    await page.route('**/api/files/upload', (route) => {
      route.abort('failed');
    });

    // Locate and interact with the file input using getByLabel
    const fileInput = page.getByLabel('Upload files');
    await fileInput.setInputFiles('playwright/fixtures/file1.pdf', 'playwright/fixtures/file2.jpg');

    // Verify file names are displayed
    const fileList = page.getByRole('list');
    await expect(fileList).toBeVisible();

    const fileItems = page.getByRole('listitem');
    const count = await fileItems.count();
    expect(count).toBe(2);

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for error response
    await page.waitForResponse(response => 
      response.url().includes('/api/files/upload') && response.status() === 500
    );

    // Verify error message appears
    const errorMessage = page.getByText(/upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error icon is displayed
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify file list is still visible but upload failed
    await expect(fileList).toBeVisible();
  });
});
